package com.ecommerce.project.service;import com.ecommerce.project.exeptions.APIException;import com.ecommerce.project.exeptions.ResourceNotFoundException;import com.ecommerce.project.model.Category;import com.ecommerce.project.repositories.CategoryRepository;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.web.server.ResponseStatusException;import java.util.ArrayList;import java.util.List;import java.util.Optional;/** * The service class for implementing the operations related to categories. */@Servicepublic class CategoryServiceImpl implements CategoryService {    @Autowired    private CategoryRepository  categoryRepository;    /**     * Gets all the categories present in the database.     *     * @return List of categories present in the database.     */    @Override    public List<Category> getAllCategories() {        List<Category> categories = categoryRepository.findAll();        if (categories.isEmpty()) {            throw new APIException("No categories created till now.");        }        return categories;    }    /**     * Creates a new category.     *     * @param category The category to be created.     */    @Override    public void createCategory(Category category) {        Category savedCategory = categoryRepository.findByCategoryName(category.getCategoryName());        if (savedCategory != null) {            throw new APIException("Category with name " + category.getCategoryName() + " already exists");        }        categoryRepository.save(category);    }    /**     * Deletes the category using the id of the category.     *     * @param categoryId The id of the category to be deleted.     *     * @return The message after the operation.     */    @Override    public String deleteCategory(Long categoryId) {        Category category = categoryRepository.findById(categoryId)                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Category not found"));        categoryRepository.delete(category);        return "Category with categoryId - " + categoryId + " deleted successfully.";    }    /**     * Updates the category by using the id of the category.     *     * @param category The category to be updated.     * @param categoryId The id of the category that needs to be updated.     *     * @return The updated category.     */    @Override    public Category updateCategory(Category category, Long categoryId){        Category savedCategory = categoryRepository.findById(categoryId)                .orElseThrow(() -> new ResourceNotFoundException("Category", "cateogryId", categoryId));        category.setCategoryId(categoryId);        savedCategory =  categoryRepository.save(category);        return savedCategory;    }}